import { crypto } from "node:crypto";

/**
 * Compare two strings in constant time to prevent timing attacks.
 * Uses UTF-8 byte comparison via TextEncoder for proper Unicode handling.
 * 
 * @param a - First string to compare
 * @param b - Second string to compare
 * @returns true if strings are equal, false otherwise
 */
export function timingSafeEqual(a: string, b: string): boolean {
  const encoder = new TextEncoder();
  const aBytes = encoder.encode(a);
  const bBytes = encoder.encode(b);

  // Constant-time comparison
  const len = Math.max(aBytes.length, bBytes.length);
  let result = 0;

  for (let i = 0; i < len; i++) {
    result |= aBytes[i] ^ bBytes[i];
  }

  return result === 0;
}

/**
 * Generate a random delay with jitter for security purposes.
 * This helps prevent timing attacks by adding randomness to response times.
 * 
 * @param baseDelay - Base delay in milliseconds
 * @returns Promise that resolves after the delayed time
 */
export function addJitter(baseDelay: number): Promise<void> {
  const jitter = Math.floor(Math.random() * 50); // 0-50ms jitter
  const totalDelay = baseDelay + jitter;
  return new Promise((resolve) => setTimeout(resolve, totalDelay));
}

